class UserWebauthnCredentialAaguidAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAaguid returns null on a freshly created holder.
     */
    public function testAaguidNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAaguidAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAaguidAssigned());
        $this->assertNull($holder->getAaguid());
    }
}
